const outPath = path.join(__dirname, '..', 'frontend', 'config', 'guide-content', 'it', 'create-alphabet-worksheets.ts');
fs.writeFileSync(outPath, content, 'utf8');
console.log('Wrote', outPath);
console.log('Length:', content.length, 'chars');

// Verify no \\uXXXX leaks
const raw = fs.readFileSync(outPath, 'utf8');
const escapes = raw.match(/\\u[0-9a-fA-F]{4}/g);
if (escapes) {
  console.error('WARNING: Found \\uXXXX escapes:', [...new Set(escapes)]);
} else {
  console.log('OK: No \\uXXXX escapes found');
}

// Check titleTag length
const titleMatch = raw.match(/titleTag:\s*'([^']+)'/);
if (titleMatch) {
  console.log('titleTag:', titleMatch[1], '(' + titleMatch[1].length + ' chars)');
}

// Check metaDescription length
const metaMatch = raw.match(/metaDescription:\s*'([^']+)'/);
if (metaMatch) {
  console.log('metaDescription:', metaMatch[1].length, 'chars');
}
